Method.Source:
/// <summary>
/// Seeds the single parameters record with the add-on's default endpoints on first open, and
/// backfills any endpoint left blank on an existing record - so a fresh install only needs the
/// ERP instance ID, Workspace ID and Authentication token typed in. Every defaulted field stays
/// editable. The Lifecycle actions tab shows only when the capability is enabled for the
/// company (Company capabilities setup).
/// </summary>
public void init()
{
    CELTParameters parameter;

    if (!CELTParameters::exist())
    {
        ttsbegin;
        parameter.clear();
        parameter.Primary               = 1;
        parameter.Environment           = CELTEnvironment::Sandbox;
        parameter.BaseURL               = CELTConstants::Default_BaseURL;
        parameter.PingURL               = CELTConstants::PingURL;
        parameter.GetCommandsURL        = CELTConstants::GetCommandURL;
        parameter.GetPresignedURL       = CELTConstants::GetPreSignedURL;
        parameter.TriggerIngestionURL   = CELTConstants::TriggerIngestionURL;
        parameter.TelemetryURL          = CELTConstants::TelemetryURL;
        parameter.AccessTokenURL        = CELTConstants::AccessTokenURL;
        parameter.GetCommandURLSync     = CELTConstants::Default_GetCommandURLSync;
        parameter.PresignedURLSync      = CELTConstants::Default_PresignedURLSync;
        parameter.GetStatusURL          = CELTConstants::Default_GetStatusURL;
        parameter.AckURL                = CELTConstants::Default_AckURL;
        parameter.DocumentPrintURL      = CELTConstants::Default_DocumentPrintURL;
        parameter.ErpInstanceID         = CELTConstants::ERPInstanceId;
        parameter.WorkspaceID           = CELTConstants::WorkspaceId;
        parameter.RetentionDays         = 30;
        parameter.insert();
        ttscommit;
    }
    else
    {
        // Backfill only what is blank - values a user (or another country setup, e.g. France)
        // has entered are never overwritten.
        boolean changed;

        ttsbegin;
        select forupdate firstonly parameter;
        if (parameter.RecId)
        {
            if (parameter.BaseURL == '')             { parameter.BaseURL             = CELTConstants::Default_BaseURL;             changed = true; }
            if (parameter.PingURL == '')             { parameter.PingURL             = CELTConstants::PingURL;                     changed = true; }
            if (parameter.GetCommandsURL == '')      { parameter.GetCommandsURL      = CELTConstants::GetCommandURL;               changed = true; }
            if (parameter.GetPresignedURL == '')     { parameter.GetPresignedURL     = CELTConstants::GetPreSignedURL;             changed = true; }
            if (parameter.TriggerIngestionURL == '') { parameter.TriggerIngestionURL = CELTConstants::TriggerIngestionURL;         changed = true; }
            if (parameter.TelemetryURL == '')        { parameter.TelemetryURL        = CELTConstants::TelemetryURL;                changed = true; }
            if (parameter.AccessTokenURL == '')      { parameter.AccessTokenURL      = CELTConstants::AccessTokenURL;              changed = true; }
            if (parameter.GetCommandURLSync == '')   { parameter.GetCommandURLSync   = CELTConstants::Default_GetCommandURLSync;   changed = true; }
            if (parameter.PresignedURLSync == '')    { parameter.PresignedURLSync    = CELTConstants::Default_PresignedURLSync;    changed = true; }
            if (parameter.GetStatusURL == '')        { parameter.GetStatusURL        = CELTConstants::Default_GetStatusURL;        changed = true; }
            if (parameter.AckURL == '')              { parameter.AckURL              = CELTConstants::Default_AckURL;              changed = true; }
            if (parameter.DocumentPrintURL == '')    { parameter.DocumentPrintURL    = CELTConstants::Default_DocumentPrintURL;    changed = true; }

            if (changed)
            {
                parameter.update();
            }
        }
        ttscommit;
    }

    super();

    element.design().controlName(formControlStr(CELTParameters, TabLifecycle)).visible(CELTLifecycleActionService::isLifecycleActionsVisible());
}
